	}

	/**
	 * Sets the body from transfer-encoded text. ARG1 must be base64 or quoted-printable; other values, including 7bit, 8bit, binary, an unknown name, or an empty string, cause failure. Base64 whitespace is accepted and the stored representation is normalized. Invalid Base64 causes the method to return _FALSE_. On any failure, all existing headers and body content are preserved unchanged.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkMimeRef.html#SetBodyFromEncoded
	 * @param ?string $encoding
	 * @param ?string $str
	 * @return bool
	 */
	function SetBodyFromEncoded($encoding,$str) {
		return CkMime_SetBodyFromEncoded($this->_cPtr,$encoding,$str);
	}

	/**
	 * Reads the local file at ARG1 and replaces the current part's body and content headers according to the filename extension. File kindResult .txttext/plain; charset=windows-1252; format=flowed, 7bit .htmltext/html; charset=windows-1252, 7bit Unknown extensionapplication/octet-stream, base64, attachment, and filename/name parameters based on the local filename
	 * @see https://www.chilkatsoft.com/refdoc/phpCkMimeRef.html#SetBodyFromFile
	 * @param ?string $fileName
	 * @return bool
	 */
	function SetBodyFromFile($fileName) {
		return CkMime_SetBodyFromFile($this->_cPtr,$fileName);
	}

	/**
	 * Sets ARG1 as HTML and changes the media type to text/html. For ASCII input, Chilkat uses Content-Transfer-Encoding: 7bit and does not add a charset. Existing unrelated headers are preserved.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkMimeRef.html#SetBodyFromHtml
	 * @param ?string $str
	 * @return bool
	 */
	function SetBodyFromHtml($str) {
		return CkMime_SetBodyFromHtml($this->_cPtr,$str);
	}

	/**
	 * Sets ARG1 as plain text. For ASCII input, Chilkat sets Content-Type: text/plain; format=flowed and Content-Transfer-Encoding: 7bit without a charset. For non-ASCII UTF-8 input, it sets charset=utf-8 and uses 8bit. Existing unrelated headers are preserved.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkMimeRef.html#SetBodyFromPlainText
	 * @param ?string $str
	 * @return bool
	 */
	function SetBodyFromPlainText($str) {
		return CkMime_SetBodyFromPlainText($this->_cPtr,$str);
	}

	/**
	 * Sets ARG1 as XML, changes the media type to text/xml, and selects a transfer encoding appropriate for the text. For ASCII input, Chilkat uses 7bit and does not add a charset. The XML declaration's encoding value is not copied to the MIME charset parameter.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkMimeRef.html#SetBodyFromXml
	 * @param ?string $str
	 * @return bool
	 */
	function SetBodyFromXml($str) {
		return CkMime_SetBodyFromXml($this->_cPtr,$str);
	}

	/**
	 * Sets one header field named by ARG1. Matching is case-insensitive. All existing occurrences are removed and one replacement is inserted. If no field exists, a new one is added. Passing an empty ARG2 removes all matching occurrences rather than creating an empty-valued field. Use AddHeaderField to append another occurrence or to create an empty-valued field.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkMimeRef.html#SetHeaderField
	 * @param ?string $name
	 * @param ?string $value
	 * @return bool
	 */
	function SetHeaderField($name,$value) {
		return CkMime_SetHeaderField($this->_cPtr,$name,$value);
	}

	/**
	 * Supplies ARG1 as a signer-certificate fallback for subsequent signature verification. This is useful when the CMS/PKCS #7 signature does not embed the signer certificate and Chilkat cannot otherwise locate it. Only the public key is required. This does not require a particular signer. An embedded signer certificate takes precedence. If the CMS signature embeds the correct signer certificate, verification can succeed even when ARG1 is an unrelated certificate, and LastSignerCert returns the embedded certificate. To enforce signer identity, verify first and then compare the returned signer certificate using application-defined criteria such as its serial number, fingerprint, subject, issuer, or trusted chain.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkMimeRef.html#SetVerifyCert
	 * @param CkCert $cert
	 * @return bool
	 */
	function SetVerifyCert($cert) {
		return CkMime_SetVerifyCert($this->_cPtr,$cert);
	}

	/**
	 * Removes supported S/MIME security layers and restores the underlying MIME content. It handles both common layer orders: a message signed and then encrypted, and a message encrypted and then signed. It continues through nested top-level layers until no additional supported security wrapper remains. After a successful call, NumSignerCerts and LastSignerCert identify verified signers, while NumDecryptCerts and LastDecryptCert identify decryption certificates. GetLastJsonData may contain both pkcs7.verify and pkcs7.decrypt details.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkMimeRef.html#UnwrapSecurity
	 * @return bool
	 */
	function UnwrapSecurity() {
		return CkMime_UnwrapSecurity($this->_cPtr);
	}

	/**
	 * Replaces the current body with an application/x-www-form-urlencoded-style representation using the character set named by ARG1. Spaces become +, a literal plus becomes %2B, non-ASCII bytes become %HH sequences, and separators such as & and = remain unchanged. Input:  a b+c&d=e Output: a+b%2Bc&d=e The MIME content headers are not changed. If the named character set is unsupported, the body remains unchanged.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkMimeRef.html#UrlEncodeBody
	 * @param ?string $charset
	 */
	function UrlEncodeBody($charset) {
		CkMime_UrlEncodeBody($this->_cPtr,$charset);
	}

	/**
	 * Sets ARG1 as the certificate vault used to locate certificates and private keys for S/MIME encryption, decryption, signing, and verification. Only one vault is active; each call replaces the previously configured vault. Use XmlCertVault when credentials are maintained independently of platform certificate stores or individual PFX sources.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkMimeRef.html#UseCertVault
	 * @param CkXmlCertVault $vault
	 * @return bool
	 */
	function UseCertVault($vault) {
		return CkMime_UseCertVault($this->_cPtr,$vault);
	}

	/**
	 * Verifies the current CMS/PKCS #7 signed MIME entity and removes the signature wrapper. Both detached multipart/signed messages and opaque CMS signed-data are supported. The method works with signed MIME loaded from serialized input as well as MIME signed by the current object. On success, the object is restored to the MIME structure and content that was signed, NumSignerCerts reports the verified signer count, LastSignerCert returns the signer certificate, and GetLastJsonData reports CMS verification details. A detached signature can restore the original serialization exactly, but opaque signed-data restoration is semantic and is not guaranteed to reproduce byte-for-byte identical MIME serialization.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkMimeRef.html#Verify
	 * @return bool
	 */
	function Verify() {
		return CkMime_Verify($this->_cPtr);
	}
}
